<div class="page-actions"><a class="back-link" href="<?= site_url('admin/modul/'.$slug) ?>">← Daftar tiket</a></div><section class="form-panel"><div class="form-intro"><span class="panel-overline">LAYANAN KOPERASI</span><h2><?= h($title) ?></h2><p>Ceritakan kebutuhan secara singkat. Petugas dapat menambahkan tindak lanjut tanpa meminta pengisian ulang.</p></div><form method="post" action="<?= site_url('admin/kasus/'.$slug.'/simpan') ?>"><?= csrf_input() ?><input type="hidden" name="id" value="<?= h($row['id']??'') ?>"><div class="form-grid"><?php if (!$own): ?><label class="form-full">Koperasi terkait<select name="cooperative_id"><option value="">Tidak terkait koperasi tertentu</option><?php foreach ($cooperatives as $c): ?><option value="<?= $c['id'] ?>" <?= (string)($row['cooperative_id']??'')===(string)$c['id']?'selected':'' ?>><?= h($c['name'].' · '.$c['nik']) ?></option><?php endforeach; ?></select></label><?php endif; ?><label class="form-full">Perihal <span class="required">*</span><input name="title" maxlength="255" required value="<?= h($row['title']??'') ?>" placeholder="Ringkasan kebutuhan atau masalah"></label><label class="form-full">Uraian <span class="required">*</span><textarea name="description" rows="6" minlength="10" required placeholder="Apa yang terjadi, kapan, dan bantuan apa yang diperlukan?"><?= h($row['description']??'') ?></textarea></label><?php if (!$own): ?><label>Nama pelapor / pemohon<input name="reporter_name" maxlength="160" value="<?= h($row['reporter_name']??'') ?>"></label><?php endif; ?><label>Kontak untuk balasan<input name="reporter_contact" maxlength="190" value="<?= h($row['reporter_contact']??'') ?>" placeholder="Nomor telepon atau email"></label><?php if (!$own): ?><label>Petugas penanggung jawab<select name="assigned_user_id"><option value="">Belum ditugaskan</option><?php foreach ($staff as $u): ?><option value="<?= $u['id'] ?>" <?= (string)($row['assigned_user_id']??'')===(string)$u['id']?'selected':'' ?>><?= h($u['full_name']) ?></option><?php endforeach; ?></select></label><?php endif; ?></div><div class="form-actions"><button class="button button-dark" type="submit">Simpan tiket →</button><a class="button button-quiet" href="<?= site_url('admin/modul/'.$slug) ?>">Batal</a></div></form></section>
